'use strict';
const defaults={eyes:0,mouth:0,hair:0,costume:0,hairColor:'#242b3d',costumeColor:'#667af0',skinColor:'#efbf9b'};
let config={...defaults};try{const old=JSON.parse(localStorage.getItem('moon-character'));if(valid(old))config=old}catch{}
const canvas=document.querySelector('#canvas'),ctx=canvas.getContext('2d');let walking=true,facing=1,speed=1,phase=0,last=0,showRig=false;
const groups=[['eyes','ดวงตา','EYES',['มั่นใจ','กลมโต','ผ่อนคลาย']],['mouth','ปาก','MOUTH',['ยิ้ม','นิ่ง','ร่าเริง']],['hair','ทรงผม','HAIR',['แสกข้าง','ผมตั้ง','บ๊อบ']],['hairColor','สีผม','HAIR COLOR',['#242b3d','#725043','#f3d78e','#d8e1ee','#a585dd']],['costume','ชุด','COSTUME',['นักผจญภัย','นักรบ','ลำลอง']],['costumeColor','สีชุด','OUTFIT COLOR',['#667af0','#7156a6','#549f88','#bd5a5c','#d7b465']],['skinColor','สีผิว','SKIN TONE',['#efbf9b','#f6d7bf','#ca936a','#8d5d48']]];
function valid(v){return v&&Object.keys(defaults).every(k=>typeof defaults[k]==='number'?Number.isInteger(v[k])&&v[k]>=0&&v[k]<3:typeof v[k]==='string'&&/^#[0-9a-f]{6}$/i.test(v[k]))}
function controls(){document.querySelector('#controls').innerHTML=groups.map(([key,label,en,options])=>`<div class="control"><div class="control-title"><b>${label}</b><small>${en}</small></div><div class="${key.endsWith('Color')?'colors':'choices'}">${options.map((value,i)=>key.endsWith('Color')?`<button aria-label="${label} ${value}" aria-pressed="${config[key]===value}" class="swatch ${config[key]===value?'active':''}" style="background:${value}" data-key="${key}" data-color="${value}"></button>`:`<button class="choice ${config[key]===i?'active':''}" aria-pressed="${config[key]===i}" data-key="${key}" data-index="${i}">${value}</button>`).join('')}${key.endsWith('Color')?`<input aria-label="เลือก${label}" type="color" value="${config[key]}" data-key="${key}">`:''}</div></div>`).join('')}
controls();document.querySelector('#controls').addEventListener('click',e=>{const b=e.target.closest('button[data-key]');if(!b)return;config[b.dataset.key]=b.dataset.color??Number(b.dataset.index);controls();persist()});document.querySelector('#controls').addEventListener('input',e=>{if(e.target.type==='color'){config[e.target.dataset.key]=e.target.value;persist()}});
function status(s){document.querySelector('#status').textContent=s}function persist(){try{localStorage.setItem('moon-character',JSON.stringify(config))}catch{status('เบราว์เซอร์นี้ไม่อนุญาตให้บันทึกในเครื่อง')}}
// Original vector artwork. All positions are local to their articulated parent.
const INK='#171d2b';
function tint(hex,amount){const n=parseInt(hex.slice(1),16);return '#'+[n>>16,(n>>8)&255,n&255].map(v=>Math.max(0,Math.min(255,v+amount)).toString(16).padStart(2,'0')).join('')}
function shape(c,d,fill,stroke=INK,width=3.8){const p=new Path2D(d);if(fill){c.fillStyle=fill;c.fill(p)}if(stroke){c.strokeStyle=stroke;c.lineWidth=width;c.lineCap='round';c.lineJoin='round';c.stroke(p)}}
function oval(c,x,y,rx,ry,fill,stroke=null,width=3){c.beginPath();c.ellipse(x,y,rx,ry,0,0,Math.PI*2);c.fillStyle=fill;c.fill();if(stroke){c.strokeStyle=stroke;c.lineWidth=width;c.stroke()}}
function box(c,x,y,w,h,r,fill,stroke=INK,width=3){c.beginPath();c.roundRect(x,y,w,h,r);c.fillStyle=fill;c.fill();if(stroke){c.strokeStyle=stroke;c.lineWidth=width;c.stroke()}}
function stroke(c,d,color,width=3){shape(c,d,null,color,width)}
function pivot(c,x,y,angle,fn){c.save();c.translate(x,y);c.rotate(angle);fn();if(showRig){oval(c,0,0,4,4,'#bcff68',INK,1)}c.restore()}
function bone(c,length){if(showRig)stroke(c,`M0 0 L0 ${length}`,'#bcff68',2)}
function drawBoot(c){shape(c,'M-17 23 Q-21 40 -16 51 L-16 61 Q2 72 29 64 Q38 60 31 48 L15 28Z','#242d44');shape(c,'M-18 54 Q4 64 33 54 L34 62 Q12 78 -19 64Z','#b9c4f7');stroke(c,'M-12 56 Q8 66 30 57','#f7f5ff',4);shape(c,'M-14 29 L13 31 L21 46 L-15 43Z',tint(config.costumeColor,-15));stroke(c,'M-9 35 L10 37 M-8 40 L13 42','#b4c1df',2);}
function drawLeg(c,x,swing,bend){pivot(c,x,83,swing,()=>{shape(c,'M-18 0 Q-24 22 -15 55 L14 58 Q23 26 18 2Z','#273149');shape(c,'M9 6 L18 9 L13 49 L6 48Z',tint(config.costumeColor,-8),null);stroke(c,'M-14 20 Q0 25 16 21','#46506a',2);pivot(c,0,50,bend,()=>{shape(c,'M-15 0 L15 0 L15 42 Q0 49 -17 41Z','#242d41');box(c,-16,1,32,19,7,'#343e55');stroke(c,'M-13 29 L13 30','#4c5870',2);drawBoot(c);bone(c,49)});bone(c,50)})}
function drawArm(c,x,swing,back){pivot(c,x,-22,swing,()=>{shape(c,'M-12 3 Q-19 19 -10 43 L11 43 Q17 18 12 3Z',config.skinColor);shape(c,'M-15 0 Q0 -14 16 1 L19 21 L-15 27Z',config.costumeColor);shape(c,'M-13 19 L18 16 L20 23 L-13 29Z',tint(config.costumeColor,-30));if(config.costume===1)shape(c,'M-20 2 Q0 -13 19 0 L22 18 L-18 23Z','#a1b1cf');pivot(c,0,37,-.16+Math.max(0,swing)*.45,()=>{shape(c,'M-10 0 L10 0 L12 26 Q0 34 -12 25Z',config.skinColor);box(c,-14,17,28,23,8,'#253047');box(c,-11,17,22,7,3,config.costumeColor);oval(c,0,40,14,16,'#263248',INK);oval(c,5,40,7,8,config.skinColor);stroke(c,'M-9 40 L-8 46','#52617c',2);bone(c,40)});bone(c,37)})}
function drawTorso(c){const a=config.costumeColor;shape(c,'M-20 -44 Q0 -51 20 -44 L36 -28 L34 39 L28 88 Q0 100 -28 88 L-34 39 L-36 -28Z',config.costume===2?a:'#263047');if(config.costume===0){shape(c,'M-24 -45 L-38 -30 L-29 52 L-12 55 L-13 -20Z','#1c263b');shape(c,'M18 -46 L38 -29 L29 52 L10 55 L11 -19Z','#263247');shape(c,'M-24 -44 L-8 -30 L-15 -10 L-34 -34Z','#3d4e6a');shape(c,'M19 -44 L7 -30 L13 -12 L31 -34Z','#435575');stroke(c,'M-10 -27 L-10 53','#60708f',2);shape(c,'M-27 -23 L-20 -30 L28 43 L21 49Z','#b7c1d2');stroke(c,'M-22 -24 L25 43','#eef1ed',1);box(c,12,29,12,9,2,'#626d83');box(c,-31,9,12,18,3,'#20293c');stroke(c,'M-28 15 L-22 15','#5a6781',2);shape(c,'M22 57 L29 56 L24 85 L18 86Z',a)}if(config.costume===1){shape(c,'M-30 -31 L0 -18 L30 -31 L28 24 L0 43 L-28 24Z','#a1b1ca');shape(c,'M-24 -21 L0 -10 L24 -21 L20 19 L0 30 L-20 19Z','#6b7e9d');shape(c,'M0 -4 L13 11 L0 24 L-13 11Z',a);stroke(c,'M-23 32 L0 44 L23 32','#d7e0eb',3);shape(c,'M-28 47 L0 53 L28 47 L33 81 L17 91 L0 75 L-17 91 L-33 81Z',a)}if(config.costume===2){shape(c,'M-23 -40 Q0 -13 23 -40 L14 -20 Q0 -8 -14 -20Z',tint(a,-32));stroke(c,'M-8 -17 L-8 9 M8 -17 L8 9','#e1e6f3',2);box(c,-24,29,48,20,6,tint(a,-12));stroke(c,'M-17 34 L17 34','#ffffff50',2)}box(c,-32,61,64,13,4,config.costume===2?'#424d66':a);box(c,-8,60,17,15,2,'#c4cede');box(c,-3,63,7,8,1,'#68758a',null);}
function drawEyes(c){for(const side of [-1,1]){c.save();c.translate(side*30,-113);if(config.eyes===2){stroke(c,'M-13 0 Q0 -12 14 0',INK,4)}else{const tall=config.eyes===1?23:20;oval(c,0,0,17,tall,'#fff9f5',INK,2.5);oval(c,3,3,11,tall-2,'#536e9b');oval(c,4,7,9,12,'#7e9bcb');oval(c,3,0,6,14,'#1d2945');oval(c,-2,-7,5,7,'#f9ffff');oval(c,8,10,2.5,3,'#e2f5ff');stroke(c,`M-17 -${tall-5} Q-4 -${tall+6} 14 -${tall-6}`,INK,4)}stroke(c,`M-14 -31 Q0 ${config.eyes===0?-43:-37} 16 -31`,tint(config.hairColor,-10),5);c.restore()}}
function drawHair(c){const h=config.hairColor,shadow=tint(h,-16),light=tint(h,35);if(config.hair===0){shape(c,'M-88 -95 Q-108 -133 -88 -175 Q-117 -170 -115 -184 Q-73 -193 -60 -216 Q-52 -245 -5 -241 Q-76 -250 -79 -266 Q-29 -251 4 -270 Q40 -289 40 -247 Q76 -269 100 -239 Q118 -234 127 -214 L105 -220 Q129 -183 113 -151 L106 -175 Q114 -131 90 -98 L68 -103 L57 -171 Q45 -187 40 -210 Q23 -163 -15 -137 L-2 -168 Q-30 -111 -65 -101 L-57 -132 L-81 -108Z',h);shape(c,'M-84 -175 Q-50 -220 17 -231 Q-19 -203 -26 -157 Q-45 -118 -65 -106 Q-57 -151 -39 -180 Q-61 -168 -84 -150Z',shadow,null);shape(c,'M31 -239 Q82 -260 101 -222 Q77 -239 63 -223 Q61 -184 77 -156 Q49 -173 40 -207 Q35 -185 26 -177Z',shadow,null);shape(c,'M-96 -183 Q-73 -201 -58 -222 Q-27 -250 15 -244 Q-14 -236 -32 -219 Q-69 -201 -96 -183Z',light,null);shape(c,'M14 -255 Q34 -273 32 -244 L22 -232 Q28 -246 14 -255Z',light,null);shape(c,'M59 -239 Q92 -249 105 -226 Q87 -236 71 -228Z',light,null);stroke(c,'M-19 -232 Q-48 -217 -56 -190',tint(h,55),3);stroke(c,'M89 -205 Q108 -171 99 -147',light,4)}if(config.hair===1){shape(c,'M-88 -93 L-99 -144 L-111 -168 L-88 -164 L-93 -211 L-65 -194 L-50 -251 L-21 -226 L4 -275 L24 -239 L61 -263 L63 -226 L97 -237 L94 -202 L119 -186 L97 -136 L84 -94 L65 -130 L53 -174 L27 -191 L5 -156 L-8 -194 L-46 -152 L-43 -178 L-76 -121Z',h);shape(c,'M-57 -194 L-43 -231 L-21 -213 L3 -250 L-5 -216 L-28 -183Z',light,null);shape(c,'M25 -220 L53 -240 L52 -210 L86 -219 L66 -192Z',light,null);stroke(c,'M-72 -154 L-59 -180 M74 -169 L86 -189',shadow,5)}if(config.hair===2){shape(c,'M-91 -79 Q-112 -137 -94 -191 Q-83 -251 -7 -253 Q81 -257 104 -196 Q122 -141 98 -71 L69 -76 L65 -147 L48 -192 Q14 -158 -18 -153 L-18 -181 Q-54 -139 -75 -133 L-65 -81Z',h);shape(c,'M-91 -173 Q-81 -229 -25 -239 Q-54 -211 -59 -178 L-77 -149Z',light,null);shape(c,'M39 -237 Q83 -225 91 -188 Q68 -210 49 -208Z',light,null);stroke(c,'M-84 -115 L-88 -91 M90 -123 L92 -91',shadow,4)}}
function drawHead(c){const skin=config.skinColor;shape(c,'M-76 -127 Q-96 -169 -68 -197 Q-30 -222 43 -205 Q91 -189 82 -128 L80 -84 Q71 -43 15 -38 Q-50 -30 -76 -77Z',tint(config.hairColor,-15));box(c,-12,-47,27,31,9,skin);shape(c,'M-74 -145 Q-68 -187 -19 -188 Q47 -193 73 -153 L79 -110 Q76 -52 20 -47 Q-41 -38 -73 -78Z',skin);shape(c,'M-70 -91 Q-58 -59 -13 -52 Q36 -48 62 -70 Q53 -44 17 -44 Q-46 -35 -70 -72Z',tint(skin,-13),null);oval(c,-77,-91,15,21,skin,INK);stroke(c,'M-81 -99 Q-69 -104 -70 -86',tint(skin,-46),3);oval(c,78,-95,21,25,skin,INK);shape(c,'M78 -111 Q96 -107 88 -92 Q80 -83 77 -92 Q92 -101 78 -111Z',tint(skin,-35),null);drawEyes(c);oval(c,-43,-82,14,7,'#e9a097');oval(c,43,-80,14,7,'#e9a097');stroke(c,'M6 -96 L8 -90',tint(skin,-45),2);if(config.mouth===0)stroke(c,'M-9 -73 Q5 -62 21 -77','#704b49',2.8);if(config.mouth===1)stroke(c,'M-7 -72 Q4 -75 16 -71','#704b49',2.8);if(config.mouth===2){shape(c,'M-10 -76 Q5 -70 21 -78 Q20 -53 1 -61 Q-8 -64 -10 -76Z','#734856',INK,2);shape(c,'M-5 -75 Q5 -72 17 -76 L14 -70 L-2 -70Z','#fff9f4',null)}drawHair(c);if(showRig)bone(c,-118)}
function draw(c,w,h,transparent=false){c.clearRect(0,0,w,h);c.save();c.translate(w*.5,h*.66);const scale=Math.min(w/800,h/760)*1.24;c.scale(scale,scale);if(!transparent){oval(c,0,192,118,13,'#080d1855');c.beginPath();c.ellipse(0,192,181,31,0,0,Math.PI*2);c.strokeStyle='#7c95af45';c.lineWidth=1;c.stroke()}c.scale(facing,1);const s=walking?Math.sin(phase):0;c.translate(0,walking?Math.cos(phase*2)*2:0);drawArm(c,-40,s*.42,true);drawLeg(c,-18,-s*.43,walking?Math.max(0,-s)*.66:0);drawLeg(c,18,s*.43,walking?Math.max(0,s)*.66:0);drawTorso(c);drawArm(c,40,-s*.42,false);pivot(c,0,-11,s*.018,()=>drawHead(c));c.restore()}

function frame(t){if(last&&walking)phase+=Math.min((t-last)/1000,.05)*speed*6;last=t;draw(ctx,canvas.width,canvas.height);requestAnimationFrame(frame)}requestAnimationFrame(frame);
document.querySelector('#play').onclick=()=>{walking=!walking;if(!walking)phase=0;document.querySelector('#play').textContent=walking?'Ⅱ หยุดเดิน':'▶ เดิน';document.querySelector('#poseLabel').textContent=walking?'WALK CYCLE':'IDLE POSE'};
document.querySelector('#direction').onclick=()=>{facing*=-1;document.querySelector('#direction').textContent=facing===1?'↔ หันซ้าย':'↔ หันขวา'};document.querySelector('#speed').oninput=e=>{speed=Number(e.target.value);document.querySelector('#speedValue').value=speed.toFixed(1)+'×'};document.querySelector('#rig').onchange=e=>showRig=e.target.checked;
document.querySelector('#save').onclick=()=>{persist();status('บันทึกตัวละครไว้ในเครื่องแล้ว')};document.querySelector('#reset').onclick=()=>{config={...defaults};controls();persist();status('คืนค่าเริ่มต้นแล้ว')};
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.querySelector('#png').onclick=()=>{const out=document.createElement('canvas');out.width=800;out.height=760;const wasRig=showRig;showRig=false;draw(out.getContext('2d'),800,760,true);showRig=wasRig;out.toBlob(blob=>{if(blob){download(blob,'moon-character.png');status('ส่งออก PNG พื้นหลังโปร่งใสแล้ว')}})};
document.querySelector('#json').onclick=()=>{download(new Blob([JSON.stringify({version:1,appearance:config,rig:{parts:['head','torso','leftUpperArm','leftForearm','leftHand','rightUpperArm','rightForearm','rightHand','leftThigh','leftShin','leftShoe','rightThigh','rightShin','rightShoe','hair'],animation:'walk'},speed},null,2)],{type:'application/json'}),'moon-character.json');status('ส่งออกค่าตัวละคร JSON แล้ว')};
document.querySelector('#load').onclick=()=>document.querySelector('#file').click();document.querySelector('#file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>100000)throw Error();const data=JSON.parse(await file.text());if(data.version!==1||!valid(data.appearance))throw Error();config={...defaults,...Object.fromEntries(Object.keys(defaults).map(k=>[k,data.appearance[k]]))};controls();persist();status('นำเข้าตัวละครแล้ว')}catch{status('ไฟล์ไม่ถูกต้อง กรุณาใช้ JSON ที่ส่งออกจากแอปนี้')}e.target.value=''};

